import torch
import torch.nn as nn

# PTX source for fp16 GEMM (A[M,K] * B[K,N] = C[M,N])
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry gemm_fp16(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .pred   %p0;
    .reg .u32    %tid_x, %tid_y;
    .reg .u32    %block_x, %block_y;
    .reg .u64    %a_base, %b_base, %c_base;
    .reg .u32    %M, %N, %K;
    .reg .u32    %row, %col;
    .reg .u32    %k;
    .reg .u64    %addr;
    .reg .f16    %a_val, %b_val, %c_val;
    .reg .f32    %a_f32, %b_f32, %acc;

    // Load kernel parameters
    ld.param.u64 %a_base, [A];
    ld.param.u64 %b_base, [B];
    ld.param.u64 %c_base, [C];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // Thread identifiers
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %block_x, %ctaid.x;
    mov.u32 %block_y, %ctaid.y;

    // Global row / column
    mad.lo.u32 %row, %block_x, 16, %tid_x;   // row = blockIdx.x * 16 + threadIdx.x
    mad.lo.u32 %col, %block_y, 16, %tid_y;   // col = blockIdx.y * 16 + threadIdx.y

    // Boundary check
    setp.ge.u32 %p0, %row, %M;
    @%p0 bra DONE;
    setp.ge.u32 %p0, %col, %N;
    @%p0 bra DONE;

    // Accumulator (FP32)
    mov.f32 %acc, 0.0;

    // Loop over K dimension
    mov.u32 %k, 0;
LOOP_K:
    setp.ge.u32 %p0, %k, %K;
    @%p0 bra END_LOOP;

    // ---- Load A[row, k] ----
    mul.lo.u32 %addr, %row, %K;          // row * K
    add.u32    %addr, %addr, %k;        // row*K + k
    mul.wide.u32 %addr, %addr, 2;       // byte offset (fp16 = 2 bytes)
    add.u64    %addr, %a_base, %addr;
    ld.global.f16 %a_val, [%addr];

    // ---- Load B[k, col] ----
    mul.lo.u32 %addr, %k, %N;            // k * N
    add.u32    %addr, %addr, %col;      // k*N + col
    mul.wide.u32 %addr, %addr, 2;
    add.u64    %addr, %b_base, %addr;
    ld.global.f16 %b_val, [%addr];

    // Convert to FP32 and accumulate
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra LOOP_K;
END_LOOP:

    // ---- Store C[row, col] ----
    cvt.rn.f16.f32 %c_val, %acc;
    mul.lo.u32 %addr, %row, %N;          // row * N
    add.u32    %addr, %addr, %col;      // row*N + col
    mul.wide.u32 %addr, %addr, 2;
    add.u64    %addr, %c_base, %addr;
    st.global.f16 [%addr], %c_val;

DONE:
    ret;
}
'''

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that executes the fp16 GEMM
    via a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Expect A: (M, K), B: (K, N), both fp16 on CUDA
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"
        C = torch.empty(M, N, dtype=torch.float16, device='cuda')
        grid = ((M + 15) // 16, (N + 15) // 16, 1)
        block = (16, 16, 1)
        args = [
            int(A.data_ptr()),   # A pointer
            int(B.data_ptr()),   # B pointer
            int(C.data_ptr()),   # C pointer
            M, N, K              # dimensions
        ]
        ptx_launch(self.module, "gemm_fp16", grid, block, args)
        return C
